<script setup lang="ts">
import { computed, ref } from 'vue'
import { Search, MapLocation } from '@element-plus/icons-vue'
import { useAdminStore } from '../stores/admin'
import type { Encounter } from '../api/types'

const store = useAdminStore()
const query = ref('')
const selected = ref<Encounter | null>(null)
const detailOpen = ref(false)
const defaultId = computed(() => store.config?.active.settings.defaultEncounterId ?? null)
const rows = computed(() => (store.encounters?.encounters ?? []).filter(encounter => `${encounter.id} ${encounter.title} ${encounter.player.name} ${encounter.enemy.name}`.includes(query.value.trim())))
function classification(value: string) { return ({ 'recovered-tutorial-with-reconstruction-rules': '序章 · 重建规则', 'local-reconstruction-preview': '本地重建场景', 'custom-content': '自定义内容' }[value] ?? value) }
function detail(encounter: Encounter) { selected.value = encounter; detailOpen.value = true }
</script>

<template>
  <section class="page"><div class="page-heading"><div><span class="eyebrow">GAME CONTENT · ENCOUNTERS</span><h1>关卡目录</h1><p>查看服务端启用的场景、参战角色和原始战斗引用。</p></div><router-link to="/config" class="text-link">设置默认关卡</router-link></div><section class="panel heroes-panel"><div class="table-toolbar"><div class="catalog-count"><el-icon><MapLocation /></el-icon><strong>{{ store.encounters?.encounters.length ?? '—' }}</strong><span>个启用场景</span></div><el-input v-model="query" class="search-input" placeholder="搜索关卡 / 敌方 / 场景 ID" :prefix-icon="Search" clearable /></div><el-table :data="rows" v-loading="store.loading" class="clean-table"><el-table-column label="关卡" min-width="220"><template #default="{ row }"><strong>{{ row.title }}</strong><div class="table-secondary-id">{{ row.id }}</div></template></el-table-column><el-table-column label="本方" min-width="110"><template #default="{ row }">{{ row.player.name }}</template></el-table-column><el-table-column label="敌方" min-width="130"><template #default="{ row }">{{ row.enemy.name }}</template></el-table-column><el-table-column label="源战斗 ID" width="120"><template #default="{ row }">{{ row.source?.battleId ?? '—' }}</template></el-table-column><el-table-column label="状态" width="140"><template #default="{ row }"><el-tag :type="row.id === defaultId ? 'success' : 'info'">{{ row.id === defaultId ? '当前默认 · 已启用' : '已启用' }}</el-tag></template></el-table-column><el-table-column label="参数" width="90" align="right"><template #default="{ row }"><el-button type="primary" link @click="detail(row)">查看</el-button></template></el-table-column><template #empty>当前服务没有匹配的启用关卡</template></el-table></section><p class="content-source-note">显示的是当前启用场景，默认关卡以生效运营配置为准。尚未实现原版奖励与解锁规则，后台不生成虚构的掉落和关卡数值。</p><el-drawer v-model="detailOpen" title="关卡参数详情" size="540px"><div v-if="selected" class="hero-detail"><div class="hero-detail-heading"><span class="hero-initial"><el-icon><MapLocation /></el-icon></span><div><h2>{{ selected.title }}</h2><span>{{ selected.id }}</span></div></div><el-descriptions :column="1" border><el-descriptions-item label="场景 ID">{{ selected.id }}</el-descriptions-item><el-descriptions-item label="规则定义 ID">{{ selected.definitionId }}</el-descriptions-item><el-descriptions-item label="内容分类">{{ classification(selected.classification) }}</el-descriptions-item><el-descriptions-item label="本方">{{ selected.player.name }} / {{ selected.player.id }}</el-descriptions-item><el-descriptions-item label="敌方">{{ selected.enemy.name }} / {{ selected.enemy.id }}</el-descriptions-item><el-descriptions-item label="源战斗 ID">{{ selected.source?.battleId ?? '—' }}</el-descriptions-item><el-descriptions-item label="源挑战 ID">{{ selected.source?.challengeId ?? '—' }}</el-descriptions-item><el-descriptions-item label="默认选择">{{ selected.id === defaultId ? '当前生效配置的默认关卡' : '按明确场景 ID 选择' }}</el-descriptions-item></el-descriptions><h3>规则与来源说明</h3><p class="evidence-text">{{ selected.notice }}</p><el-alert title="场景参数展示源接口实际投影，不推断未提供的敌方属性、原版掉落或解锁条件。" type="info" :closable="false" /></div></el-drawer></section>
</template>
